+package org.projectnessie.catalog.files.s3;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+import org.junit.jupiter.api.Test;
+import org.projectnessie.catalog.files.config.ImmutableS3NamedBucketOptions;
+import software.amazon.awssdk.services.s3.S3Configuration;
+
+class TestS3ClientSupplier {
+
+  @Test
+  void chunkedEncodingDefaultsToAwsBehavior() {
+    S3Configuration baseline = S3Configuration.builder().build();
+    S3Configuration.Builder builder = S3Configuration.builder();
+    S3ClientSupplier.configureServiceConfiguration(
+        ImmutableS3NamedBucketOptions.builder().build(), builder);
+
+    assertThat(builder.build().chunkedEncodingEnabled())
+        .isEqualTo(baseline.chunkedEncodingEnabled());
+  }
+
+  @Test
+  void chunkedEncodingCanBeDisabledPerBucket() {
+    S3Configuration.Builder builder = S3Configuration.builder();
+    S3ClientSupplier.configureServiceConfiguration(
+        ImmutableS3NamedBucketOptions.builder().chunkedEncodingEnabled(false).build(), builder);
+
+    assertThat(builder.build().chunkedEncodingEnabled()).isFalse();
+  }
+
+  @Test
+  void chunkedEncodingCanBeEnabledPerBucket() {
+    S3Configuration.Builder builder = S3Configuration.builder();
+    S3ClientSupplier.configureServiceConfiguration(
+        ImmutableS3NamedBucketOptions.builder().chunkedEncodingEnabled(true).build(), builder);
+
+    assertThat(builder.build().chunkedEncodingEnabled()).isTrue();
+  }
+}
